    std::istringstream iss("1 2 3 4 5 6");
    std::vector<int> ints{std::istream_iterator<int>(iss), std::istream_iterator<int>()};

    for (auto [a, b] : ints | std::views::adjacent<2>) {
        std::cout << a << ',' << b << ' ';
