        auto bind_address =
            parse_port(text)
                .and_then(validate_port_range)
                .and_then(to_bind_address);

        if (bind_address) {
            std::cout << text << " -> bind on " << *bind_address << '\n';
        } else {
            std::cout << text << " -> " << bind_address.error().message << '\n';
        }
    }
}

