    print_matrix(col_major);   // ...interpreted with a different layout
}

#include <mdspan>
#include <vector>
#include <iostream>

int main() {
    std::vector<std::vector<int>> nested = {{1, 2, 3}, {4, 5, 6}};

    // Flatten into one contiguous buffer, row by row
    std::vector<int> flat;
    flat.reserve(nested.size() * nested[0].size());
    for (auto& row : nested)
