    [[assume(x >= 0)]];
    if (x < 0) { return -1; }   // optimizer may treat this as dead code
    return x * 2;
}

// ✅ Safe: assumption placed only after the fact is genuinely established
int compute(int x) {
    if (x < 0) { return -1; }
    [[assume(x >= 0)]];   // Now truly guaranteed at this point
    return x * 2;
}
```

